-- ============================================================
-- One-time migration -- add default_scope_json to service_categories
-- ============================================================
-- service_categories itself was added in schema.sql without ever being
-- deployed to production D1 in this project's history so far. This
-- migration exists defensively, in case that CREATE TABLE was already run
-- against the live database before this column was added -- ALTER TABLE ADD
-- COLUMN only works once per database, matching the caveat on every other
-- migration in this folder.
--
--   wrangler d1 execute nuvho-proposals --remote --file=./worker/migrations/0004_service_categories_default_scope.sql

ALTER TABLE service_categories ADD COLUMN default_scope_json TEXT NOT NULL DEFAULT '[]';

UPDATE service_categories SET default_scope_json = '[{"id":"sm_sec_1","heading":"New Property Set Up","items":[{"id":"sm1_1","text":"Sales Planning – Develop a sales activity plan by market segment including strategy and tactics."},{"id":"sm1_2","text":"Account Setup – Establish the properties in Pipedrive CRM, email inbox and configure reporting on an agreed basis."},{"id":"sm1_3","text":"Template Development – Where required, create a suite of templates for use in the proposal and request for tender process."}]},{"id":"sm_sec_2","heading":"Business Development","items":[{"id":"sm2_1","text":"Sales Calls & Emails – Conduct connected reactive and proactive research, sales calls and emails incorporating an agreed blend of segments to hit an average of 90 connects per month."},{"id":"sm2_2","text":"Tenders & RFPs - Undertake tenders and requests for proposals on demand based on client requirements."},{"id":"sm2_3","text":"Site Inspections - Facilitate site inspections to showcase the property to local accounts."},{"id":"sm2_4","text":"Dedicated Resource – Assign dedicated team members assigned to execute sales strategy and tactics."}]},{"id":"sm_sec_3","heading":"Account Management","items":[{"id":"sm3_1","text":"Account Management - Implement and execute account management strategies to ensure both company and TMCs are being targeted."}]},{"id":"sm_sec_4","heading":"Administration","items":[{"id":"sm4_1","text":"Reporting – Provide a monthly activity report highlighting sales activities, return on investment as well as maintain a live online dashboard identifying the forward pipeline of business."},{"id":"sm4_2","text":"Strategy Consult - Conduct on-going and interim consultation with the property to provide feedback on return on investment & performance."},{"id":"sm4_3","text":"Sales Management – Management of overall sales strategy and implementation."}]}]', updated_at = datetime('now') WHERE code = 'SM';
UPDATE service_categories SET default_scope_json = '[{"id":"mk_sec_1","heading":"Strategic Marketing Planning","items":[{"id":"mk1_1","text":"Marketing Plan Production – Produce a marketing plan for approval by the Client by hotel, restaurant, group or as directed."},{"id":"mk1_2","text":"Budget Management – Allocate and review paid media and partnerships budget monthly as required."},{"id":"mk1_3","text":"Strategy Review - Conduct on-going and interim consultation to provide feedback on return on investment & performance."}]},{"id":"mk_sec_2","heading":"Listing Management","items":[{"id":"mk2_1","text":"Business Listings – Manage static listings across Google and Bing."},{"id":"mk2_2","text":"Partnership Listings – Manage static listings with partners including ATDW, Australian Good Food Guide, Google Meta, local tourism information centres and other relevant partner sites."},{"id":"mk2_3","text":"Other Channels - Other meta channels to be discussed on a case by case basis."}]},{"id":"mk_sec_3","heading":"Social Media Management","items":[{"id":"mk3_1","text":"Campaign Creation – Campaign creation includes strategizing and scheduling of social media across Facebook & Instagram channels (additional channels such as TikTok & Pinterest to be considered on request). Content creation is focused on agreed content pillars suitable to the Client and the market."},{"id":"mk3_2","text":"Artwork – Directly liaise with the Client personnel in relation to artwork production for campaigns, with images and videography to be supplied by the hotel. Content can be coordinated by Nuvho on an as-need basis."},{"id":"mk3_3","text":"Posting and Scheduling - Build a content calendar to plan, schedule, and manage the distribution of 10 posts per month across approved channels, spanning a mix of content types."},{"id":"mk3_4","text":"Monitoring and Improving – Monitor content results to continually work to enhance performance of posts and themes that attract more engagement."},{"id":"mk3_5","text":"Social Listening – Monitor and respond to follower messages and comments within a timely manner."}]},{"id":"mk_sec_4","heading":"Direct Marketing Campaigns","items":[{"id":"mk4_1","text":"Account Setup – Establish the account in the nominated CRM and connect the relevant opt-in funnels to the CRM in a segmented manner."},{"id":"mk4_2","text":"Template Development – Establish a suite of templates including standardised header and footer."},{"id":"mk4_3","text":"EDM Production – Produce EDMs as directed, circulate for internal review prior to client release."},{"id":"mk4_4","text":"Reporting – Provide feedback reporting on campaigns undertaken."}]},{"id":"mk_sec_5","heading":"Database Management","items":[{"id":"mk5_1","text":"Account Setup – Establish the database in the nominated CRM and connect the relevant interfaces to the CRM in a segmented manner."},{"id":"mk5_2","text":"Segmentation – Segment the database by property in an appropriate manner including website leads, property management system & booking engine and other segments as provided."}]},{"id":"mk_sec_6","heading":"Website Development","items":[{"id":"mk6_1","text":"Supply - Supply and host an independently branded accommodation website based on the Nuvho template."},{"id":"mk6_2","text":"Booking Widgets - Customise integration of the booking engine mask for reservations of the accommodation and/or other departments."},{"id":"mk6_3","text":"Integration - Connect a range of third-party content to the site including but not limited to Instagram, social media, CRM and Trip Advisor review widgets into each site."},{"id":"mk6_4","text":"SEO – Undertake organic search-engine optimisation on the site backend to manage search engine optimisation."},{"id":"mk6_5","text":"Analytics – Connect and configure each page for tracking on the clients Google Analytics account. Connect Google Search Console and index the site upon completion."},{"id":"mk6_6","text":"Responsiveness – Our platform inherently includes optimisation across all mobile and desktop platforms."},{"id":"mk6_7","text":"Testing – Conduct full user testing on the following operating systems/devices prior to a live launch date - iOS: Safari, Android, Google Chrome and Firefox."},{"id":"mk6_8","text":"Security – Issue generic SSL Certificates to enhance security and provide consumer comfort."},{"id":"mk6_9","text":"Imagery, Video, Advertising & Gallery – The Divi platform can accommodate a range of imagery and video content that can be easily edited."},{"id":"mk6_10","text":"Tracking & Reporting – Provide reporting on site visitation data derived from Google Analytics."},{"id":"mk6_11","text":"Support – Include four hours of support per year incorporating edits and changes as requested. Subsequent changes are charged on an hourly basis."}]},{"id":"mk_sec_7","heading":"Booking Engine – Simple Booking","items":[{"id":"mk7_1","text":"Supply – Supply Simple Booking software under licence from Qnt Srl."}]},{"id":"mk_sec_8","heading":"Seamless Guest Journey – Accommodation Correspondence","items":[{"id":"mk8_1","text":"Correspondence – Required correspondence includes confirmation letter (HTML), pre-stay (HTML minus 7 days), day-of-arrival (HTML), post-stay (HTML plus one day), cancellation letter (HTML) and registration card (PDF)."},{"id":"mk8_2","text":"Draft – Produce a draft structure outline for each template that will form the basis of the development process and agree with the client before proceeding."},{"id":"mk8_3","text":"Components – Specific elements of the templates where appropriate will include the following: Personalisation (personalise the correspondence utilising the specific property management system short-codes); Reservation Details (provide reservation details specific to the profile of correspondence); Upselling (as well as rich content for the integrated tours and activities product, include client specified products to upsell); Manage my Booking (provide clear buttons that link to the client portal of the property management system in order to modify or update reservations); Property Reviews (establish an avenue for guests to leave reviews for the subject property)."},{"id":"mk8_4","text":"Review – Present the suite of templates for review and make amendments as directed."},{"id":"mk8_5","text":"Load – Load the templates within the property management system and booking engine as required."}]},{"id":"mk_sec_9","heading":"Photography Management","items":[{"id":"mk9_1","text":"Photographer Engagement – Review existing local photographer skills and quotes and engage an appropriate photographer."},{"id":"mk9_2","text":"Photography Brief – Produce a detailed brief for the photographer incorporating the following: equipment list appropriate to the desired shots including drone and appropriate 360-degree footage; prop list outlining the props to be utilised per shot including appropriate room, restaurant, bar, meetings and seasonal props for forward social media campaigns; best practice example photography footage showcasing ideal outputs; and shot list detailing the number of shots per each element of the property including aspect and time of day."},{"id":"mk9_3","text":"Photographer Liaison – Liaise with the photographer prior to the shoot day to overview the photography brief and during the shoot to discuss any particular shots and scenes."},{"id":"mk9_4","text":"Property Liaison – Liaise with the property prior to the shoot day to ensure the property set-up, as per the photography brief, has been undertaken and completed."},{"id":"mk9_5","text":"Photograph Selection – Review the photographs and select the appropriate suite of photographs to professionally represent the property."},{"id":"mk9_6","text":"Photography Dissemination – Coordinate and manage the dissemination of the selected photographs across sales channels."}]},{"id":"mk_sec_10","heading":"Collateral Production","items":[{"id":"mk10_1","text":"Collateral Production – Create draft collateral for pre-approval and roll out on respective channels or print once approved."},{"id":"mk10_2","text":"Printing Coordination – Coordinate with nominated printing outlets for production of collateral and distribution."}]},{"id":"mk_sec_11","heading":"Brand Development","items":[{"id":"mk11_1","text":"Internal Consultation & Workshop – Conduct an internal focus group to identify key insights pertaining to the subject property and brand positioning relative to competition, market segment, target audience and likely building profiles."},{"id":"mk11_2","text":"Brand Strategy – Define the brand''s mission, vision, values, and unique selling proposition. Conduct market research and analysis to identify the brand''s target audience, competitors, and positioning within the market."},{"id":"mk11_3","text":"Logo Design – Present scalable and adaptable logo options for different applications and produce mock-ups of the logo for client selection."},{"id":"mk11_4","text":"Visual Identity – Establish the brand''s visual identity by defining colour palettes, typography, and graphic elements that align with the brand''s values and positioning. Create basic guidelines for consistent usage of these visual elements across various brand touchpoints."},{"id":"mk11_5","text":"Brand Messaging - Develop a brand voice and tone that reflects the brand''s personality and resonates with the target audience. Craft key messages, taglines, and brand story to effectively communicate the brand''s values and offerings."},{"id":"mk11_6","text":"Approval – The brand development stages may require consultation sessions and will require sign-off to ensure satisfaction in the approval process, before moving to output."},{"id":"mk11_7","text":"Brand Guidelines – Including the hotel messaging, tone of voice, key words, tagline, target customer, USPs, competitive matrix, ambitions, brand positioning, character, assets, brand experience pillars."},{"id":"mk11_8","text":"Logos – Generate full logo suite in .AI, PNG and JPEG formats."},{"id":"mk11_9","text":"Develop Supporting Graphic Elements – Hotel factsheet, key card & key holder, compendium, DND hanger, mini bar slips, room service menus, bar menus, internal and external signage, posters, letterheads, business cards, email signature, with-compliments slip, email invitation, tent cards, A5 notepads, pens."}]},{"id":"mk_sec_12","heading":"Influencer / Content Creator Marketing","items":[{"id":"mk12_1","text":"Sourcing – Proactively source influencers/content creators that fit the client''s target market and requirements."},{"id":"mk12_2","text":"Management – Negotiate with influencers/content creators to ensure deliverables are received within time frame and messaging aligns with the client''s tone of voice."},{"id":"mk12_3","text":"Account Management – Engage with the influencer/content creator post-stay to pre-approve content and receive any feedback from their stay."}]},{"id":"mk_sec_13","heading":"Paid Media","items":[{"id":"mk13_1","text":"Google Setup – Setup Google hotel ads sponsored connectivity."},{"id":"mk13_2","text":"Meta Setup – Setup Meta ads connectivity."},{"id":"mk13_3","text":"Content – Directly liaise with Client personnel in relation to content production for campaigns, with images to be supplied by the hotel."},{"id":"mk13_4","text":"Hotel Tracking Setup – Audit and setup tracking across the sponsored connectivity consumer journey to report on return on investment and digital performance. Tracking includes both Google and Meta channels."},{"id":"mk13_5","text":"Campaign Types – Ad types will be selected based on overall goals and budget and may be adjusted as needed, including: Brand Protection (Google Search Ads) - strategic use of branded keyword campaigns to safeguard the online identity, ensuring visibility and preventing competitor encroachment; Keywords Unbranded (Google Ads) - using general, non-brand terms to search for the accommodation without referencing a specific company name; Performance Max (Google Ads) - includes Search, Display, YouTube, Discover, Maps and Gmail with a mix of static and video content; Demand Generation (Google Ads) - designed to attract high-intent audiences, increase brand visibility and drive qualified traffic; Meta Retargeting - reconnect with potential guests who have already shown interest by sending them relevant ads that encourage them to return and complete their booking; Meta Traffic Generation - attract high quality visitors to the website who are most likely to book."},{"id":"mk13_6","text":"Paid Media Budget – Effectively manage the approved paid media budget."}]}]', updated_at = datetime('now') WHERE code = 'MK';
UPDATE service_categories SET default_scope_json = '[{"id":"rm_sec_1","heading":"Revenue Management Services","items":[{"id":"rm_1","text":"Audit – Conduct market assessment and market share analysis to inform broad recommendations for yield strategy based on the value matrix."},{"id":"rm_2","text":"Setup – Setup property across our various systems and create process efficiencies."},{"id":"rm_3","text":"Revenue 365 - Supply a daily report comprising a 365-day rolling forecast and incorporating market pricing & competitor pricing."},{"id":"rm_4","text":"Strategy Consultation - Conduct 3 x weekly strategy sessions with the property with recommendations on pricing implementation."},{"id":"rm_5","text":"Room & Rate Strategy – Review and set up the room structure, pricing matrix, value matrix, interface across systems and propagate across channels."},{"id":"rm_6","text":"Yield Management - Manage overall pricing and yield management including updating and propagation of rates across channels."},{"id":"rm_7","text":"OTA Management - Ongoing management of OTA channels, relationships, accounts and represent the property with OTA account managers."},{"id":"rm_8","text":"GDS Management - Ongoing management of GDS relationships and represent the property with GDS account managers."},{"id":"rm_9","text":"Forecasting - Provide rolling top-line twelve-month forecasts."},{"id":"rm_10","text":"Budget – Provide twelve-month rooms revenue budget broken down into market segments per month; provided once per contract year."},{"id":"rm_11","text":"Reporting - Provide reporting measuring performance against the competitive set and the same period last year including an end of month report focusing on key revenue metrics."}]}]', updated_at = datetime('now') WHERE code = 'RM';
UPDATE service_categories SET default_scope_json = '[{"id":"cr_sec_1","heading":"Reservation Management Services","items":[{"id":"cr_1","text":"Systems Setup – Setup the systems associated with the provision of central reservations including the reservations system, telephony system and chatbot."},{"id":"cr_2","text":"Hours & Location of Service – Provide reservations hours of service from Monday to Friday 9am to 5pm."},{"id":"cr_3","text":"Property Research & Training – Coordinate training with the property such that in-depth knowledge of room types and facilities is present."},{"id":"cr_4","text":"Sales Training – Provide appropriate sales training to reservation personnel in terms of telephony manner, connection, conversion and upselling."},{"id":"cr_5","text":"Inbound Reservation Handling – Handle all inbound accommodation reservation enquiries from telephone and email channels at all stages of the reservation process from enquiry, proposal, execution, cancellation and post-stay."},{"id":"cr_6","text":"Manage Existing Reservations – Manage existing reservations with PMS access."},{"id":"cr_7","text":"Lead Generation – Pass appropriate leads to the sales team of the property in terms of corporate and MICE segments as well as any other prospective account management leads."},{"id":"cr_8","text":"Report Generation – Generate and distribute daily arrivals and no-show reports. Produce monthly reporting on activity comprising calls, proposals, conversion and up-sales."}]}]', updated_at = datetime('now') WHERE code = 'CR';
